import{_ as i,o as n,c as a,ai as l}from"./chunks/framework.BxxKhjs3.js";const p="/pub-blog/assets/image-20240902230122815.DumBn54v.png",h="/pub-blog/assets/image-20240902231634937.C5n-hMXD.png",e="/pub-blog/assets/image-20240902223823376.CG_z_zBG.png",t="/pub-blog/assets/image-20240902224250634.YDGVsyPZ.png",k="/pub-blog/assets/image-20240902224949027.COSpmMJ7.png",r="/pub-blog/assets/image-20240902225153206.UGVsd8xU.png",E="/pub-blog/assets/image-20240902232718492.DxlW8CO8.png",d="/pub-blog/assets/PixPin_2024-09-02_23-34-06.CJK4GO6Q.gif",g="/pub-blog/assets/image-20240902234252101.DnSQrT0N.png",y="/pub-blog/assets/image-20240902234447382.0iOYM4U_.png",c="/pub-blog/assets/image-20240903000807542.81IT_pMH.png",F="/pub-blog/assets/image-20240903001343178.QCQjNXfN.png",o="/pub-blog/assets/image-20240903001128023.BLuUDXc6.png",b="/pub-blog/assets/image-20240903001214873.B2ym9wij.png",u="/pub-blog/assets/image-20240903001146480.Nm2DVOEg.png",C="/pub-blog/assets/PixPin_2024-09-03_00-15-58.IAiYAUZI.gif",m="/pub-blog/assets/image-20240903001515500.BuxoDDzG.png",B="/pub-blog/assets/PixPin_2024-09-03_00-19-15.HtNmmuS3.gif",A="/pub-blog/assets/image-20240903002417398.CQ5KOQhq.png",D="/pub-blog/assets/PixPin_2024-09-03_00-26-12.Da45WE-L.gif",x="/pub-blog/assets/PixPin_2024-09-03_21-55-36.CeBqz6V3.gif",f="/pub-blog/assets/PixPin_2024-09-03_22-11-52.B7002Flg.gif",T="/pub-blog/assets/image-20240904104914079.CkEgePzb.png",q="/pub-blog/assets/image-20240904110251815.DFsRIgOV.png",v="/pub-blog/assets/PixPin_2024-09-04_11-12-28.n7TzXjBm.gif",P="/pub-blog/assets/image-20240904115859088.DFWDNZ14.png",w="/pub-blog/assets/image-20240904120111649.DH3vy86x.png",S="/pub-blog/assets/image-20240904120045126.CAZ-LAYw.png",O="/pub-blog/assets/image-20240904120023853.Dj-VorHt.png",V="/pub-blog/assets/PixPin_2024-09-04_12-02-35.BKLy6J2o.gif",$=JSON.parse('{"title":"带你实现 HarmonyOS Next 微信聊天 01","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next 微信聊天/带你实现HarmonyOS Next 微信聊天01/带你实现HarmonyOS Next 微信聊天01.md","filePath":"鸿蒙开发技巧/HarmonyOS Next 微信聊天/带你实现HarmonyOS Next 微信聊天01/带你实现HarmonyOS Next 微信聊天01.md","lastUpdated":1730788610000,"__rawMarkdown":"# 带你实现 HarmonyOS Next 微信聊天 01\\n\\n## 前言\\n\\n代码会统一放在码云上，纯静态的完整代码会放在末尾\\n\\n\\n\\n## 案例目标\\n\\n> 这个是安卓手机上的真正的微信聊天界面功能效果\\n\\n![image-20240902230122815](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240902230122815.png)\\n\\n## 实际效果\\n\\n![image-20240902231634937](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240902231634937.png)\\n\\n## 案例功能\\n\\n1. 页面沉浸式\\n2. 聊天内容滚动\\n3. 输入框状态切换\\n4. 聊天信息框宽度自适应\\n5. 输入法避让\\n6. 语音消息根据时长自动宽度\\n7. canvas 声纹 按住说话\\n8. 手势坐标检测取消发送-语音转文字\\n9. 发送文字\\n10. 录音-发送语音\\n11. 声音播放-语音消息\\n12. AI 语音转文字\\n\\n## 新建项目\\n\\n![image-20240902223823376](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240902223823376.png)\\n\\n## 修改项目桌面名称和图标\\n\\n![image-20240902224250634](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240902224250634.png)\\n\\n1. `entry\\\\src\\\\main\\\\resources\\\\zh_CN\\\\element\\\\string.json`\\n   1. ```TypeScript\\n      {\\n        \\"string\\": [\\n          {\\n            \\"name\\": \\"module_desc\\",\\n            \\"value\\": \\"模块描述\\"\\n          },\\n          {\\n            \\"name\\": \\"EntryAbility_desc\\",\\n            \\"value\\": \\"description\\"\\n          },\\n          {\\n            \\"name\\": \\"EntryAbility_label\\",\\n            \\"value\\": \\"我的聊天项目\\" // 😄\\n          }\\n        ]\\n      }\\n      ```\\n2. `\\\\entry\\\\src\\\\main\\\\module.json5`\\n   1. ```TypeScript\\n      ...\\n      \\"abilities\\": [\\n        {\\n          \\"name\\": \\"EntryAbility\\",\\n          \\"srcEntry\\": \\"./ets/entryability/EntryAbility.ets\\",\\n          \\"description\\": \\"$string:EntryAbility_desc\\",\\n          \\"icon\\": \\"$media:chat\\",😄\\n          ...\\n      ```\\n\\n> $media:chat 来自于 resource 下的名为 chat 的图标\\n\\n![image-20240902224949027](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240902224949027.png)\\n\\n## 设置沉浸式\\n\\n![image-20240902225153206](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240902225153206.png)\\n\\n1. **图一**为默认情况下的页面布局，可以看到我们的页面是无法触及到**顶部状态栏**和**底部菜单栏**的\\n2. **图二**为设置了沉浸式效果后，布局按钮可以触及到顶部状态栏了\\n3. **图三**为动态获取到了顶部状态栏的高度，然后给容器添加了相应的 padding，挤压布局元素到顶部状态栏的下方\\n\\n### 设置沉浸式和获取顶部状态栏高度\\n\\n`\\\\entry\\\\src\\\\main\\\\ets\\\\entryability\\\\EntryAbility.ets`\\n\\n```typescript\\n...\\nonWindowStageCreate(windowStage: window.WindowStage): void {\\n  // Main window is created, set main page for this ability\\n  hilog.info(0x0000, \'testTag\', \'%{public}s\', \'Ability onWindowStageCreate\');\\n\\n  windowStage.loadContent(\'pages/Index\', (err) => {\\n    if (err.code) {\\n      hilog.error(0x0000, \'testTag\', \'Failed to load the content. Cause: %{public}s\', JSON.stringify(err) ?? \'\');\\n      return;\\n    }\\n    hilog.info(0x0000, \'testTag\', \'Succeeded in loading the content.\');\\n          //   设置应用全屏\\n    let windowClass: window.Window = windowStage.getMainWindowSync(); // 获取应用主窗口\\n\\n    windowClass.setWindowLayoutFullScreen(true)\\n\\n    let type = window.AvoidAreaType.TYPE_NAVIGATION_INDICATOR; // 导航条避让\\n    let avoidArea = windowClass.getWindowAvoidArea(type);\\n\\n    let bottomRectHeight = avoidArea.bottomRect.height; // 获取到导航条区域的高度\\n\\n\\n    const vpHeight = px2vp(bottomRectHeight) //  转换成 vp单位的数值\\n\\n\\n    //    把导航栏高度数据 存在全局\\n    AppStorage.setOrCreate(\\"vpHeight\\", vpHeight)\\n  });\\n}\\n...\\n```\\n\\n### 页面使用导航栏高度设置 padding\\n\\n```typescript\\n@Entry\\n@Component\\nstruct Index {\\n  @StorageProp(\\"vpHeight\\")\\n  topHeight: number = 0\\n\\n  build() {\\n    Column() {\\n      Button(\\"按钮\\")\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .backgroundColor(Color.Yellow)\\n    .padding({\\n      top: this.vpHeight,\\n    })\\n  }\\n}\\n```\\n\\n## 搭建页面基本布局\\n\\n![image-20240902232718492](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240902232718492.png)\\n\\n```\\n@Entry\\n@Component\\nstruct Index {\\n  // 状态栏高度\\n  @StorageProp(\\"vpHeight\\")\\n  vpHeight: number = 0\\n\\n  build() {\\n    Column() {\\n         // 1 顶部标题栏\\n      Row() {\\n        Image($r(\\"app.media.left\\"))\\n          .width(25)\\n        Text(\\"kto卋讓硪玩孫悟空\\")\\n        Image($r(\\"app.media.more\\"))\\n          .width(25)\\n      }\\n      .width(\\"100%\\")\\n      .justifyContent(FlexAlign.SpaceBetween)\\n      .border({\\n        width: {\\n          bottom: 1\\n        },\\n        color: \\"#ddd\\"\\n      })\\n      .padding(10)\\n       // 2 聊天滚动容器\\n       // 3 输入面板\\n\\n\\n    }\\n    .height(\'100%\')\\n    .width(\'100%\')\\n    .backgroundColor(\\"#EDEDED\\")\\n    .padding({\\n      top: this.vpHeight + 20\\n    })\\n  }\\n\\n}\\n```\\n\\n## 页面滚动和文字信息框\\n\\n![PixPin_2024-09-02_23-34-06](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/PixPin_2024-09-02_23-34-06.gif)\\n\\n```typescript\\n  build() {\\n    Column() {\\n      // 1 顶部标题栏\\n.....\\n      // 2 聊天滚动容器\\n      Scroll() {\\n        Column({ space: 10 }) {\\n            this.chatTextBuilder(\\"吃饭\\", `22:23`)\\n        }\\n        .width(\\"100%\\")\\n        .padding(10)\\n        .justifyContent(FlexAlign.Start)\\n\\n      }\\n      .layoutWeight(1)\\n      .align(Alignment.Top)\\n\\n      .expandSafeArea([SafeAreaType.KEYBOARD], [SafeAreaEdge.BOTTOM])\\n    }\\n    .height(\'100%\')\\n    .width(\'100%\')\\n    .backgroundColor(\\"#EDEDED\\")\\n    .backgroundImageSize(ImageSize.Cover)\\n    .padding({\\n      top: this.vpHeight + 20\\n    })\\n  }\\n  // 文字消息\\n  @Builder\\n  chatTextBuilder(text: string, time: string) {\\n    Column({ space: 5 }) {\\n      Text(time)\\n        .width(\\"100%\\")\\n        .textAlign(TextAlign.Center)\\n        .fontColor(\\"#666\\")\\n        .fontSize(14)\\n      Row() {\\n        Flex({ justifyContent: FlexAlign.End }) {\\n          Row() {\\n            Text(text)\\n              .padding(11);\\n            Text()\\n              .width(10)\\n              .height(10)\\n              .backgroundColor(\\"#93EC6C\\")\\n              .position({\\n                right: 0,\\n                top: 15\\n              })\\n              .translate({\\n                x: 5,\\n              })\\n              .rotate({\\n                angle: 45\\n              });\\n\\n          }\\n          .backgroundColor(\\"#93EC6C\\")\\n          .margin({ right: 15 })\\n          .borderRadius(5);\\n\\n          Image($r(\\"app.media.avatar\\"))\\n            .width(40)\\n            .aspectRatio(1);\\n        }\\n        .width(\\"100%\\");\\n      }\\n      .width(\\"100%\\")\\n      .padding({\\n        left: 40\\n      })\\n      .justifyContent(FlexAlign.End)\\n    }\\n    .width(\\"100%\\")\\n  }\\n```\\n\\n### 亮点\\n\\n![image-20240902234252101](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240902234252101.png)\\n\\n以下代码是实现上面，自适应宽度的关键\\n\\n1. 当文字较小时，绿色聊天框宽度自适应\\n2. 当文字较多时，绿色聊天框宽度自动变宽，但是不会铺满一行，微信也是这样设计的\\n\\n![image-20240902234447382](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240902234447382.png)\\n\\n## 底部消息发送框\\n\\n### 显示输入框还是 \\"按住说话\\"\\n\\n![image-20240903000807542](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240903000807542.png)\\n\\n可以看到，底部消息发送框起码有三种状态\\n\\n1. 按住说话\\n2. 文本输入框\\n3. 文本输入框 - 发送\\n\\n程序中，通过枚举决定 按住说话-文本输入框两种状态\\n\\n```typescript\\n/**\\n * 当前输入状态 语音或者文本\\n */\\nenum WXInputType {\\n  /**\\n   * 语音输入\\n   */\\n  voice = 0,\\n  /**\\n   * 文本输入\\n   */\\n  text = 1,\\n}\\n```\\n\\n---\\n\\n![image-20240903001343178](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240903001343178.png)\\n\\n### 显示 “发送” 按钮\\n\\n另外，通过判断文本输入的长度来决定 是否显示 绿色的 **发送**\\n\\n![image-20240903001128023](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240903001128023.png)\\n\\n---\\n\\n![image-20240903001214873](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240903001214873.png)\\n\\n---\\n\\n![image-20240903001146480](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240903001146480.png)\\n\\n### 显示文本输入框自动获得焦点\\n\\n![PixPin_2024-09-03_00-15-58](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/PixPin_2024-09-03_00-15-58.gif)\\n\\n![image-20240903001515500](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240903001515500.png)\\n\\n## 设置输入时 键盘避让\\n\\n不设置避让时，可以看到底部聊天被弹出的键盘顶上去了。\\n\\n![PixPin_2024-09-03_00-19-15](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/PixPin_2024-09-03_00-19-15.gif)\\n\\n### 解决方法\\n\\n设置拓展安全区域为软键盘区域，同时设置扩展安全区域的方向为下方区域\\n\\n![image-20240903002417398](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240903002417398.png)\\n\\n---\\n\\n![PixPin_2024-09-03_00-26-12](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/PixPin_2024-09-03_00-26-12.gif)\\n\\n##\\n\\n## 发送文本消息\\n\\n![PixPin_2024-09-03_21-55-36](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/PixPin_2024-09-03_21-55-36.gif)\\n\\n### 定义消息类型枚举\\n\\n```typescript\\nenum MessageType {\\n  /**\\n   * 声音\\n   */\\n  voice = 0,\\n  /**\\n   * 文本\\n   */\\n  text = 1,\\n}\\n```\\n\\n### 定义消息类\\n\\n用来快速生成消息对象，可以表示语音消息和文本消息\\n\\n```typescript\\n// 消息\\nclass ChatMessage {\\n  /**\\n   * 消息类型：【录音、文本】\\n   */\\n  type: MessageType\\n  /**\\n   * 内容 [录音-文件路径，文本-内容]\\n   */\\n  content: string\\n  /**\\n   * 消息时间\\n   */\\n  time: string\\n  /**\\n   * 声音的持续时间 单位毫秒\\n   */\\n  duration?: number\\n  /**\\n   * 录音转的文字\\n   */\\n  translateText?: string\\n  /**\\n   * 是否显示转好的文字\\n   */\\n  isShowTranslateText: boolean = false\\n\\n  constructor(\\n    type: MessageType,\\n    content: string,\\n    duration?: number,\\n    translateText?: string\\n  ) {\\n    this.type = type\\n    this.content = content\\n    const date = new Date()\\n    this.time = `${date.getHours().toString().padStart(2, \'0\')}:${date\\n      .getMinutes()\\n      .toString()\\n      .padStart(2, \'0\')}`\\n    this.duration = duration\\n    this.translateText = translateText\\n  }\\n}\\n```\\n\\n### 定义消息数组\\n\\n```typescript\\n  // 消息\\n  @State\\n  chatList: ChatMessage[] = []\\n```\\n\\n### 定义发送文本消息的方法\\n\\n```typescript\\n// 发送文本消息\\nsendTextMessage = () => {\\n  if (!this.textValue.trim()) {\\n    return\\n  }\\n  const chat = new ChatMessage(MessageType.text, this.textValue.trim())\\n  this.chatList.push(chat)\\n  this.textValue = \'\'\\n}\\n```\\n\\n### 注册发送文本消息事件\\n\\n```typescript\\nButton(\'发送\')\\n  .backgroundColor(\'#08C060\')\\n  .type(ButtonType.Normal)\\n  .fontColor(\'#fff\')\\n  .borderRadius(5)\\n  .onClick(this.sendTextMessage)\\n```\\n\\n### 遍历消息数组\\n\\n```typescript\\n  //   2 聊天滚动容器\\n  Scroll() {\\n    Column({ space: 10 }) {\\n      ForEach(this.chatList, (item: ChatMessage, index: number) => {\\n        if (item.type === MessageType.text) {\\n          this.chatTextBuilder(item.content, item.time)\\n        }\\n      })\\n    }.width(\\"100%\\")\\n    .padding(10)\\n    .justifyContent(FlexAlign.Start)\\n\\n  }\\n  .layoutWeight(1)\\n  .align(Alignment.Top)\\n  .expandSafeArea([SafeAreaType.KEYBOARD], [SafeAreaEdge.BOTTOM])\\n```\\n\\n## 按住说话\\n\\n![PixPin_2024-09-03_22-11-52](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/PixPin_2024-09-03_22-11-52.gif)\\n\\n### 定义是否正在说话的变量\\n\\n```typescript\\n  // 按住说话 录音模态\\n  @State\\n  showTalkContainer: boolean = false\\n```\\n\\n### 注册触摸事件 Touch\\n\\n长按 **按住说话**时触发， Touch 事件是会持续触发的，通过判断 event.type 来获知 触摸状态\\n\\n1. down 按下\\n2. move 移动\\n3. up 松开\\n\\n```typescript\\nButton(\'按住说话\')\\n  .layoutWeight(1)\\n  .type(ButtonType.Normal)\\n  .borderRadius(5)\\n  .backgroundColor(\'#fff\')\\n  .fontColor(\'#000\')\\n  .onTouch(this.onPressTalk)\\n```\\n\\n---\\n\\n### 定义 this.onPressTalk\\n\\n```typescript\\n// 按住说话 持续触发\\nonPressTalk = async (event: TouchEvent) => {\\n  if (event.type === TouchType.Down) {\\n    // 按下\\n    this.showTalkContainer = true\\n  } else if (event.type === TouchType.Up) {\\n    // 松开手\\n    this.showTalkContainer = false\\n  }\\n}\\n```\\n\\n### 实现全屏遮罩效果\\n\\n该效果利用鸿蒙应用中的**全模态**实现 [**bindContentCover**](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/ts-universal-attributes-modal-transition-V5#bindcontentcover)\\n\\n给组件绑定全屏模态页面，点击后显示模态页面。模态页面内容自定义，显示方式可设置无动画过渡，上下切换过渡以及透明渐变过渡方式。\\n\\n> this.talkContainerBuilder 为全模态出现时对应的内容布局，它是一个自定义构建函数\\n\\n```typescript\\nButton(\'按住说话\')\\n  .layoutWeight(1)\\n  .type(ButtonType.Normal)\\n  .borderRadius(5)\\n  .backgroundColor(\'#fff\')\\n  .fontColor(\'#000\')\\n  .bindContentCover($$this.showTalkContainer, this.talkContainerBuilder, {\\n    modalTransition: ModalTransition.NONE,\\n  })\\n  .onTouch(this.onPressTalk)\\n```\\n\\n---\\n\\n### 定义 this.talkContainerBuilder\\n\\n```typescript\\n  // 正在说话 页面布局\\n  @Builder\\n  talkContainerBuilder() {\\n    Column() {\\n      //   1 中心的提示\\n      Row() {\\n        Text()\\n          .width(10)\\n          .height(10)\\n          .backgroundColor(\\"#95EC6A\\")\\n          .position({\\n            bottom: -5,\\n            left: \\"50%\\"\\n          })\\n          .translate({\\n            x: \\"-50%\\"\\n          })\\n          .rotate({\\n            angle: 45\\n          })\\n      }\\n      .width(\\"50%\\")\\n      .height(80)\\n      .backgroundColor(\\"#95EC6A\\")\\n      .position({\\n        top: \\"40%\\",\\n        left: \\"50%\\"\\n      })\\n      .translate({\\n        x: \\"-50%\\"\\n      })\\n      .borderRadius(10)\\n      .justifyContent(FlexAlign.Center)\\n      .alignItems(VerticalAlign.Center)\\n\\n      //   2 取消和转文字\\n      Row() {\\n\\n        Row() {\\n          Text(\\"X\\")\\n            .fontSize(20)\\n            .width(60)\\n            .height(60)\\n            .borderRadius(30)\\n            .fontColor(\\"#000\\")\\n            .backgroundColor(\\"#fff\\")\\n            .textAlign(TextAlign.Center)\\n            .align(Alignment.Center)\\n            .fontColor(\\"#ccc\\")\\n            .id(\\"aabb\\")\\n            .rotate({ angle: -20 })\\n\\n        }\\n\\n        Row() {\\n          Text(\\"文\\")\\n            .fontSize(20)\\n            .width(60)\\n            .height(60)\\n            .borderRadius(30)\\n            .fontColor(\\"#ccc\\")\\n            .backgroundColor(\\"#333\\")\\n            .textAlign(TextAlign.Center)\\n            .align(Alignment.Center)\\n            .id(\\"ddee\\")\\n            .rotate({ angle: 20 })\\n        }\\n\\n        // 3  松开发送\\n        Text(\\"松开发送\\")\\n          .fontColor(\\"#fff\\")\\n          .width(\\"100%\\")\\n          .position({\\n            bottom: 0,\\n            left: 0\\n          })\\n          .textAlign(TextAlign.Center)\\n      }\\n      .width(\\"100%\\")\\n      .position({\\n        bottom: \\"23%\\"\\n      })\\n      .justifyContent(FlexAlign.SpaceBetween)\\n      .padding({\\n        left: 60, right: 60\\n      })\\n\\n\\n      //   4 底部白色大球\\n      Row() {\\n\\n      }\\n      .width(600)\\n      .height(600)\\n      .backgroundColor(\\"#fff\\")\\n      .position({\\n        bottom: 0,\\n        left: \\"50%\\"\\n      })\\n      .translate({\\n        x: \\"-50%\\",\\n        y: \\"70%\\"\\n      })\\n      .borderRadius(\\"50%\\")\\n\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .backgroundColor(\\"rgba(0,0,0,0.5)\\")\\n  }\\n```\\n\\n## 说话声纹\\n\\n![image-20240904104914079](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240904104914079.png)\\n\\n这个绿色容器中的波纹，是通过 canva 来描述的，真正的逻辑应该是监听或者获取当前声音音量的大小，然后根据它转换对应的波纹。但是没有在鸿蒙中直接找到 api，查阅资料发现需要自己分析音频文件数据，自己转化才可以，时间关系就没有继续往下实现。使用随机数简单模拟了下。\\n\\n### 配置 CanvasRenderingContext2D 对象的参数\\n\\n```typescript\\n//用来配置 CanvasRenderingContext2D 对象的参数，包括是否开启抗锯齿，true表明开启抗锯齿。\\nsettings: RenderingContextSettings = new RenderingContextSettings(true)\\n```\\n\\n### 用来创建 CanvasRenderingContext2D 对象\\n\\n```typescript\\n//用来创建CanvasRenderingContext2D对象，通过在canvas中调用CanvasRenderingContext2D对象来绘制。\\ncontext: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)\\n```\\n\\n### 定义声纹自定义构建函数\\n\\n这里使用 canvas 画布技术，在`onReady` 生命周期函数中 通过开启一个定时器，在定时器中不断重复以下过程\\n\\n1. 通过**clearRect** 清空上一次描绘的波纹\\n2. 通过 **fillRect** 随机描绘这一次的波纹\\n\\n最后，如果此组件被销毁了，可以在 **onDisAppear** 中停止定时器\\n\\n```typescript\\n  /**\\n   * 录音中的 动态声纹波浪\\n   */\\n  @Builder\\n  vocalPrint() {\\n    Canvas(this.context)\\n      .onDisAppear(() => {\\n        clearInterval(this.voiceTimeId)\\n      })\\n      .width(\'80%\')\\n      .height(\'80%\')\\n      .onReady(() => {\\n        //可以在这里绘制内容。\\n        clearInterval(this.voiceTimeId)\\n        this.voiceTimeId = setInterval(() => {\\n          this.context.clearRect(0, 0, 1000, 1000)\\n          for (let index = 0; index < 35; index++) {\\n            const random = Math.floor(Math.random() * 10)\\n            let height = 20 + random\\n            this.context.fillRect(0 + index * 5, 32 - height / 2, 2, height);\\n          }\\n        }, 100)\\n      })\\n  }\\n```\\n\\n### 使用声纹自定义构造函数\\n\\n![image-20240904110251815](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240904110251815.png)\\n\\n## 发送信息-取消发送\\n\\n![PixPin_2024-09-04_11-12-28](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/PixPin_2024-09-04_11-12-28.gif)\\n\\n这部分的 UI 交互相对来说比较复杂，当按住 **按住说话** 时：\\n\\n1. 手指移动到 **X**， 表示取消发送\\n2. 手指移动到**文**，表示转换文字\\n3. 手指直接松开时，发送录音\\n\\n这部分功能的核心思想时，检测手指是否移动到了相应的元素，触发对应的业务逻辑即可。但是现实的问题是，找不到合适的事件，比如元素引入事件，所以后期采取的是检测手指在整个屏幕的坐标是否触及到了 **X** 和 **文** 来实现。\\n\\n### 定义长按状态的枚举\\n\\n1. 没有长按\\n2. 长按\\n3. 长按-**X**\\n4. 长按-**文**\\n\\n```typescript\\nenum PressCancelVoicePostText {\\n  // 没有长按\\n  none = 0,\\n  //   长按 没有选中“取消发送”或者\\"转语音\\"\\n  presssing = 1,\\n  //   取消发送\\n  cancelVoice = 2,\\n  //   转文字\\n  postText = 3,\\n}\\n```\\n\\n### 定义手指坐标类型\\n\\n```typescript\\n/**\\n * 长按时，手指的坐标\\n */\\ninterface ScreenOffset {\\n  x: number\\n  y: number\\n  width: number\\n  height: number\\n}\\n```\\n\\n### 定义长按状态\\n\\n```typescript\\n// 长按状态\\n@State\\npressCancelVoicePostText: PressCancelVoicePostText = PressCancelVoicePostText.none\\n```\\n\\n### 定义 X 和 文的坐标状态\\n\\n```typescript\\n// “x ”的坐标\\nxScreenOffset: ScreenOffset = {\\n  x: 0,\\n  y: 0,\\n  width: 0,\\n  height: 0,\\n}\\nTextScreenOffset: ScreenOffset = {\\n  x: 0,\\n  y: 0,\\n  width: 0,\\n  height: 0,\\n}\\n```\\n\\n### 实时获取 X 和 文 的坐标\\n\\n在组件中监听 **onAppear** 事件，根据组件的唯一标识**id**来获取坐标数据\\n\\n![image-20240904115859088](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240904115859088.png)\\n\\n#### X\\n\\n```typescript\\nText(\'X\')\\n  .fontSize(20)\\n  .width(60)\\n  .height(60)\\n  .borderRadius(30)\\n  .fontColor(\\n    this.pressCancelVoicePostText === PressCancelVoicePostText.cancelVoice\\n      ? \'#000\'\\n      : \'#ccc\'\\n  )\\n  .backgroundColor(\\n    this.pressCancelVoicePostText === PressCancelVoicePostText.cancelVoice\\n      ? \'#fff\'\\n      : \'#333\'\\n  )\\n  .textAlign(TextAlign.Center)\\n  .align(Alignment.Center)\\n  .fontColor(\'#ccc\')\\n  .id(\'aabb\')\\n  .rotate({ angle: -20 })\\n  .onAppear(() => {\\n    let modePosition: componentUtils.ComponentInfo =\\n      componentUtils.getRectangleById(\'aabb\')\\n    this.xScreenOffset.x = px2vp(modePosition.screenOffset.x)\\n    this.xScreenOffset.y = px2vp(modePosition.screenOffset.y)\\n    this.xScreenOffset.width = px2vp(modePosition.size.width)\\n    this.xScreenOffset.height = px2vp(modePosition.size.height)\\n  })\\n```\\n\\n#### 文\\n\\n```typescript\\nText(\'文\')\\n  .fontSize(20)\\n  .width(60)\\n  .height(60)\\n  .borderRadius(30)\\n  .fontColor(\\n    this.pressCancelVoicePostText === PressCancelVoicePostText.postText\\n      ? \'#000\'\\n      : \'#ccc\'\\n  )\\n  .backgroundColor(\\n    this.pressCancelVoicePostText === PressCancelVoicePostText.postText\\n      ? \'#fff\'\\n      : \'#333\'\\n  )\\n  .textAlign(TextAlign.Center)\\n  .align(Alignment.Center)\\n  .id(\'ddee\')\\n  .rotate({ angle: 20 })\\n  .onAppear(() => {\\n    let modePosition: componentUtils.ComponentInfo =\\n      componentUtils.getRectangleById(\'ddee\')\\n    // px单位\\n    this.TextScreenOffset.x = px2vp(modePosition.screenOffset.x)\\n    this.TextScreenOffset.y = px2vp(modePosition.screenOffset.y)\\n    this.TextScreenOffset.width = px2vp(modePosition.size.width)\\n    this.TextScreenOffset.height = px2vp(modePosition.size.height)\\n  })\\n```\\n\\n### 调整 touch 事件 onPressTalk 的逻辑\\n\\n该函数的调整逻辑是 判断当前手指的坐标是否触碰到了 **X** 或者 **文** ， 然后设置对应的状态\\n\\n```typescript\\n// 按住说话 持续触发\\nonPressTalk = async (event: TouchEvent) => {\\n  if (event.type === TouchType.Down) {\\n    // 手指按下时触发\\n    this.pressCancelVoicePostText = PressCancelVoicePostText.presssing\\n    // 按下\\n    this.showTalkContainer = true\\n  } else if (event.type === TouchType.Move) {\\n    // 手指移动时持续触发\\n    this.pressCancelVoicePostText = PressCancelVoicePostText.presssing\\n    // 获取当前手指的坐标\\n    const x = event.touches[0].displayX\\n    const y = event.touches[0].displayY\\n    // 判断是否碰到了 “X”\\n    let isTouchX =\\n      this.xScreenOffset.x <= x &&\\n      this.xScreenOffset.x + this.xScreenOffset.width >= x &&\\n      this.xScreenOffset.y <= y &&\\n      this.xScreenOffset.y + this.xScreenOffset.width >= y\\n    // 判断是否碰到了 \\"文\\"\\n    let isTouchText =\\n      this.TextScreenOffset.x <= x &&\\n      this.TextScreenOffset.x + this.TextScreenOffset.width >= x &&\\n      this.TextScreenOffset.y <= y &&\\n      this.TextScreenOffset.y + this.TextScreenOffset.width >= y\\n    if (isTouchX) {\\n      // 取消发送\\n      this.pressCancelVoicePostText = PressCancelVoicePostText.cancelVoice\\n    } else if (isTouchText) {\\n      // 转换文字\\n      this.pressCancelVoicePostText = PressCancelVoicePostText.postText\\n    }\\n  } else if (event.type === TouchType.Up) {\\n    // 松开手\\n    this.showTalkContainer = false\\n    if (this.pressCancelVoicePostText === PressCancelVoicePostText.postText) {\\n      // 转换文字\\n    } else if (\\n      this.pressCancelVoicePostText === PressCancelVoicePostText.cancelVoice\\n    ) {\\n      // 取消发送\\n    } else {\\n      // 发送录音\\n    }\\n  }\\n}\\n```\\n\\n### 添加 X 和 文字的 样式\\n\\n![image-20240904120111649](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240904120111649.png)\\n\\n当 `this.pressCancelVoicePostText` 状态发生改变时，需要调整 对应的组件的样式\\n\\n![image-20240904120045126](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240904120045126.png)\\n\\n---\\n\\n![image-20240904120023853](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/image-20240904120023853.png)\\n\\n### 调整声纹容器的样式\\n\\n![PixPin_2024-09-04_12-02-35](%E5%B8%A6%E4%BD%A0%E5%AE%9E%E7%8E%B0HarmonyOS%20Next%20%E5%BE%AE%E4%BF%A1%E8%81%8A%E5%A4%A901.assets/PixPin_2024-09-04_12-02-35.gif)\\n\\n1. 如果当前正在录音，显示正常绿色的声纹\\n2. 如果当前取消发送，显示取消红色的声纹\\n3. 如果当前转换文字，显示绿色的空的内容-_后期存放实时的语音转换的文字_\\n\\n```typescript\\n      //   1 中心的提示   显示波浪线\\n      Row() {\\n        if (this.pressCancelVoicePostText !== PressCancelVoicePostText.postText) {\\n          // 声纹\\n          this.vocalPrint()\\n\\n        } else {\\n          Scroll() {\\n            // 显示录音的文字\\n            Text(\\"\\")\\n              .fontSize(12)\\n              .fontColor(\\"#666\\")\\n          }\\n          .width(\\"100%\\")\\n          .height(\\"100%\\")\\n        }\\n\\n        Text()\\n          .width(10)\\n          .height(10)\\n          .backgroundColor(this.pressCancelVoicePostText === PressCancelVoicePostText.cancelVoice ? Color.Red :\\n            \\"#95EC6A\\")\\n          .position({\\n            bottom: -5,\\n            left: \\"50%\\"\\n          })\\n          .translate({\\n            x: \\"-50%\\"\\n          })\\n          .rotate({\\n            angle: 45\\n          })\\n      }\\n      .width(\\"50%\\")\\n      .height(80)\\n      .backgroundColor(this.pressCancelVoicePostText === PressCancelVoicePostText.cancelVoice ? Color.Red : \\"#95EC6A\\")\\n      .position({\\n        top: \\"40%\\",\\n        left: \\"50%\\"\\n      })\\n      .translate({\\n        x: \\"-50%\\"\\n      })\\n      .borderRadius(10)\\n      .justifyContent(FlexAlign.Center)\\n      .alignItems(VerticalAlign.Center)\\n```\\n\\n## 完整代码\\n\\n```typescript\\n/**\\n * 当前输入状态 语音或者文本\\n */\\nimport { componentUtils } from \'@kit.ArkUI\'\\n\\nenum WXInputType {\\n  /**\\n   * 语音输入\\n   */\\n  voice = 0,\\n  /**\\n   * 文本输入\\n   */\\n  text = 1\\n}\\n\\nenum MessageType {\\n  /**\\n   * 声音\\n   */\\n  voice = 0,\\n  /**\\n   * 文本\\n   */\\n  text = 1\\n}\\n\\n// 消息\\nclass ChatMessage {\\n  /**\\n   * 消息类型：【录音、文本】\\n   */\\n  type: MessageType\\n  /**\\n   * 内容 [录音-文件路径，文本-内容]\\n   */\\n  content: string\\n  /**\\n   * 消息时间\\n   */\\n  time: string\\n  /**\\n   * 声音的持续时间 单位毫秒\\n   */\\n  duration?: number\\n  /**\\n   * 录音转的文字\\n   */\\n  translateText?: string\\n  /**\\n   * 是否显示转好的文字\\n   */\\n  isShowTranslateText: boolean = false\\n\\n  constructor(type: MessageType, content: string, duration?: number, translateText?: string) {\\n    this.type = type\\n    this.content = content\\n    const date = new Date()\\n    this.time = `${date.getHours().toString().padStart(2, \'0\')}:${date.getMinutes().toString().padStart(2, \'0\')}`\\n    this.duration = duration\\n    this.translateText = translateText\\n  }\\n}\\n\\nenum PressCancelVoicePostText {\\n  // 没有长按\\n  none = 0,\\n  //   长按 没有选中“取消发送”或者\\"转语音\\"\\n  presssing = 1,\\n  //   取消发送\\n  cancelVoice = 2,\\n  //   转文字\\n  postText = 3\\n}\\n\\n\\n/**\\n * 长按时，手指的坐标\\n */\\ninterface ScreenOffset {\\n  x: number\\n  y: number\\n  width: number\\n  height: number\\n}\\n\\n@Entry\\n@Component\\nstruct Index {\\n  // 状态栏高度\\n  @StorageProp(\\"vpHeight\\")\\n  vpHeight: number = 0\\n  // 输入框内容\\n  @State\\n  textValue: string = \\"\\"\\n  // 输入状态 语音或者文字\\n  @State\\n  inputType: WXInputType = WXInputType.voice\\n  // 消息\\n  @State\\n  chatList: ChatMessage[] = []\\n  // 按住说话 录音模态\\n  @State\\n  showTalkContainer: boolean = false\\n  // 长按状态\\n  @State\\n  pressCancelVoicePostText: PressCancelVoicePostText = PressCancelVoicePostText.none\\n  //用来配置 CanvasRenderingContext2D 对象的参数，包括是否开启抗锯齿，true表明开启抗锯齿。\\n  settings: RenderingContextSettings = new RenderingContextSettings(true)\\n  //用来创建CanvasRenderingContext2D对象，通过在canvas中调用CanvasRenderingContext2D对象来绘制。\\n  context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)\\n  // 声明波纹定时器id\\n  voiceTimeId: number = -1\\n  // “x ”的坐标\\n  xScreenOffset: ScreenOffset = {\\n    x: 0,\\n    y: 0,\\n    width: 0,\\n    height: 0\\n  }\\n  TextScreenOffset: ScreenOffset = {\\n    x: 0,\\n    y: 0,\\n    width: 0,\\n    height: 0\\n  }\\n  // 发送文本消息\\n  sendTextMessage = () => {\\n    if (!this.textValue.trim()) {\\n      return\\n    }\\n    const chat = new ChatMessage(MessageType.text, this.textValue.trim())\\n    this.chatList.push(chat)\\n    this.textValue = \\"\\"\\n  }\\n  // 按住说话 持续触发\\n  onPressTalk = async (event: TouchEvent) => {\\n    if (event.type === TouchType.Down) {\\n      // 手指按下时触发\\n      this.pressCancelVoicePostText = PressCancelVoicePostText.presssing\\n      // 按下\\n      this.showTalkContainer = true\\n\\n    } else if (event.type === TouchType.Move) {\\n      // 手指移动时持续触发\\n      this.pressCancelVoicePostText = PressCancelVoicePostText.presssing\\n      // 获取当前手指的坐标\\n      const x = event.touches[0].displayX\\n      const y = event.touches[0].displayY\\n      // 判断是否碰到了 “X”\\n      let isTouchX = this.xScreenOffset.x <= x && this.xScreenOffset.x + this.xScreenOffset.width >= x &&\\n        this.xScreenOffset.y <= y && this.xScreenOffset.y + this.xScreenOffset.width >= y\\n      // 判断是否碰到了 \\"文\\"\\n      let isTouchText = this.TextScreenOffset.x <= x && this.TextScreenOffset.x + this.TextScreenOffset.width >= x &&\\n        this.TextScreenOffset.y <= y && this.TextScreenOffset.y + this.TextScreenOffset.width >= y\\n      if (isTouchX) {\\n        // 取消发送\\n        this.pressCancelVoicePostText = PressCancelVoicePostText.cancelVoice\\n      } else if (isTouchText) {\\n        // 转换文字\\n        this.pressCancelVoicePostText = PressCancelVoicePostText.postText\\n      }\\n    } else if (event.type === TouchType.Up) {\\n      // 松开手\\n      this.showTalkContainer = false\\n      if (this.pressCancelVoicePostText === PressCancelVoicePostText.postText) {\\n        // 转换文字\\n      } else if (this.pressCancelVoicePostText === PressCancelVoicePostText.cancelVoice) {\\n        // 取消发送\\n      } else {\\n        // 发送录音\\n      }\\n    }\\n  }\\n\\n  build() {\\n    Column() {\\n      // 1 顶部标题栏\\n      Row() {\\n        Image($r(\\"app.media.left\\"))\\n          .width(25)\\n        Text(\\"kto卋讓硪玩孫悟空\\")\\n        Image($r(\\"app.media.more\\"))\\n          .width(25)\\n      }\\n      .width(\\"100%\\")\\n      .justifyContent(FlexAlign.SpaceBetween)\\n      .border({\\n        width: {\\n          bottom: 1\\n        },\\n        color: \\"#ddd\\"\\n      })\\n      .padding(10)\\n      .expandSafeArea([SafeAreaType.KEYBOARD], [SafeAreaEdge.BOTTOM])\\n\\n      //   2 聊天滚动容器\\n      Scroll() {\\n        Column({ space: 10 }) {\\n          ForEach(this.chatList, (item: ChatMessage, index: number) => {\\n            if (item.type === MessageType.text) {\\n              this.chatTextBuilder(item.content, item.time)\\n            }\\n          })\\n        }.width(\\"100%\\")\\n        .padding(10)\\n        .justifyContent(FlexAlign.Start)\\n\\n      }\\n      .layoutWeight(1)\\n      .align(Alignment.Top)\\n      .expandSafeArea([SafeAreaType.KEYBOARD], [SafeAreaEdge.BOTTOM])\\n\\n      //   3 底部聊天发送框\\n      Row({ space: 5 }) {\\n        if (WXInputType.text === this.inputType) {\\n          Image($r(\\"app.media.voice\\"))\\n            .width(40)\\n            .fillColor(\\"#333\\")\\n            .borderRadius(20)\\n            .border({ width: 2 })\\n            .onClick(() => {\\n              this.inputType = WXInputType.voice\\n            })\\n          TextInput({ text: $$this.textValue })\\n            .onAppear(() => {\\n              // 自动显示焦点\\n              this.getUIContext().getFocusController().requestFocus(\\"textinput1\\")\\n            })\\n            .layoutWeight(1)\\n            .backgroundColor(\\"#fff\\")\\n            .borderRadius(3)\\n            .defaultFocus(true)\\n            .id(\\"textinput1\\")\\n        } else if (WXInputType.voice === this.inputType) {\\n          Image($r(\\"app.media.keyboard\\"))\\n            .width(40)\\n            .fillColor(\\"#333\\")\\n            .borderRadius(20)\\n            .border({ width: 2 })\\n            .onClick(() => {\\n              this.inputType = WXInputType.text\\n            })\\n          Button(\\"按住说话\\")\\n            .layoutWeight(1)\\n            .type(ButtonType.Normal)\\n            .borderRadius(5)\\n            .backgroundColor(\\"#fff\\")\\n            .fontColor(\\"#000\\")\\n            .bindContentCover($$this.showTalkContainer, this.talkContainerBuilder,\\n              { modalTransition: ModalTransition.NONE })\\n            .onTouch(this.onPressTalk)\\n\\n        }\\n\\n        Image($r(\\"app.media.smile\\"))\\n          .width(40)\\n          .fillColor(\\"#333\\")\\n\\n        if (this.textValue.length) {\\n          Button(\\"发送\\")\\n            .backgroundColor(\\"#08C060\\")\\n            .type(ButtonType.Normal)\\n            .fontColor(\\"#fff\\")\\n            .borderRadius(5)\\n            .onClick(this.sendTextMessage)\\n        } else {\\n          Image($r(\\"app.media.plus\\"))\\n            .width(48)\\n            .fillColor(\\"#333\\")\\n        }\\n      }\\n      .width(\\"100%\\")\\n      .padding(10)\\n      .backgroundColor(\\"#F7F7F7\\")\\n    }\\n    .height(\'100%\')\\n    .width(\'100%\')\\n    .backgroundColor(\\"#EDEDED\\")\\n    .backgroundImageSize(ImageSize.Cover)\\n    .padding({\\n      top: this.vpHeight + 20\\n    })\\n  }\\n\\n  // 文字消息\\n  @Builder\\n  chatTextBuilder(text: string, time: string) {\\n    Column({ space: 5 }) {\\n      Text(time)\\n        .width(\\"100%\\")\\n        .textAlign(TextAlign.Center)\\n        .fontColor(\\"#666\\")\\n        .fontSize(14)\\n      Row() {\\n        Flex({ justifyContent: FlexAlign.End }) {\\n          Row() {\\n            Text(text)\\n              .padding(11);\\n            Text()\\n              .width(10)\\n              .height(10)\\n              .backgroundColor(\\"#93EC6C\\")\\n              .position({\\n                right: 0,\\n                top: 15\\n              })\\n              .translate({\\n                x: 5,\\n              })\\n              .rotate({\\n                angle: 45\\n              });\\n          }\\n          .backgroundColor(\\"#93EC6C\\")\\n          .margin({ right: 15 })\\n          .borderRadius(5);\\n\\n          Image($r(\\"app.media.avatar\\"))\\n            .width(40)\\n            .aspectRatio(1);\\n        }\\n        .width(\\"100%\\");\\n      }\\n      .width(\\"100%\\")\\n      .padding({\\n        left: 40\\n      })\\n      .justifyContent(FlexAlign.End)\\n    }\\n    .width(\\"100%\\")\\n  }\\n\\n  // 正在说话 页面布局\\n  @Builder\\n  talkContainerBuilder() {\\n    Column() {\\n      //   1 中心的提示   显示波浪线\\n      Row() {\\n        if (this.pressCancelVoicePostText !== PressCancelVoicePostText.postText) {\\n          // 声纹\\n          this.vocalPrint()\\n\\n        } else {\\n          Scroll() {\\n            // 显示录音的文字\\n            Text(\\"\\")\\n              .fontSize(12)\\n              .fontColor(\\"#666\\")\\n          }\\n          .width(\\"100%\\")\\n          .height(\\"100%\\")\\n        }\\n\\n        Text()\\n          .width(10)\\n          .height(10)\\n          .backgroundColor(this.pressCancelVoicePostText === PressCancelVoicePostText.cancelVoice ? Color.Red :\\n            \\"#95EC6A\\")\\n          .position({\\n            bottom: -5,\\n            left: \\"50%\\"\\n          })\\n          .translate({\\n            x: \\"-50%\\"\\n          })\\n          .rotate({\\n            angle: 45\\n          })\\n      }\\n      .width(\\"50%\\")\\n      .height(80)\\n      .backgroundColor(this.pressCancelVoicePostText === PressCancelVoicePostText.cancelVoice ? Color.Red : \\"#95EC6A\\")\\n      .position({\\n        top: \\"40%\\",\\n        left: \\"50%\\"\\n      })\\n      .translate({\\n        x: \\"-50%\\"\\n      })\\n      .borderRadius(10)\\n      .justifyContent(FlexAlign.Center)\\n      .alignItems(VerticalAlign.Center)\\n\\n      //   2 取消和转文字\\n      Row() {\\n        Row() {\\n          Text(\\"X\\")\\n            .fontSize(20)\\n            .width(60)\\n            .height(60)\\n            .borderRadius(30)\\n            .fontColor(this.pressCancelVoicePostText === PressCancelVoicePostText.cancelVoice ? \\"#000\\" : \\"#ccc\\")\\n            .backgroundColor(this.pressCancelVoicePostText === PressCancelVoicePostText.cancelVoice ? \\"#fff\\" : \\"#333\\")\\n            .textAlign(TextAlign.Center)\\n            .align(Alignment.Center)\\n            .fontColor(\\"#ccc\\")\\n            .id(\\"aabb\\")\\n            .rotate({ angle: -20 })\\n            .onAppear(() => {\\n              let modePosition: componentUtils.ComponentInfo = componentUtils.getRectangleById(\\"aabb\\");\\n              this.xScreenOffset.x = px2vp(modePosition.screenOffset.x)\\n              this.xScreenOffset.y = px2vp(modePosition.screenOffset.y)\\n              this.xScreenOffset.width = px2vp(modePosition.size.width)\\n              this.xScreenOffset.height = px2vp(modePosition.size.height)\\n            })\\n        }\\n\\n        Row() {\\n          Text(\\"文\\")\\n            .fontSize(20)\\n            .width(60)\\n            .height(60)\\n            .borderRadius(30)\\n            .fontColor(this.pressCancelVoicePostText === PressCancelVoicePostText.postText ? \\"#000\\" : \\"#ccc\\")\\n            .backgroundColor(this.pressCancelVoicePostText === PressCancelVoicePostText.postText ? \\"#fff\\" : \\"#333\\")\\n            .textAlign(TextAlign.Center)\\n            .align(Alignment.Center)\\n            .id(\\"ddee\\")\\n            .rotate({ angle: 20 })\\n            .onAppear(() => {\\n              let modePosition: componentUtils.ComponentInfo = componentUtils.getRectangleById(\\"ddee\\");\\n              // px单位\\n              this.TextScreenOffset.x = px2vp(modePosition.screenOffset.x)\\n              this.TextScreenOffset.y = px2vp(modePosition.screenOffset.y)\\n              this.TextScreenOffset.width = px2vp(modePosition.size.width)\\n              this.TextScreenOffset.height = px2vp(modePosition.size.height)\\n            })\\n\\n        }\\n\\n        // 3  松开发送\\n        Text(this.pressCancelVoicePostText === PressCancelVoicePostText.cancelVoice ? \'取消发送\' :\\n          (this.pressCancelVoicePostText === PressCancelVoicePostText.postText ? \'转换文字\' : \\"松开发送\\"))\\n          .fontColor(\\"#fff\\")\\n          .width(\\"100%\\")\\n          .position({\\n            bottom: 0,\\n            left: 0\\n          })\\n          .textAlign(TextAlign.Center)\\n      }\\n      .width(\\"100%\\")\\n      .position({\\n        bottom: \\"23%\\"\\n      })\\n      .justifyContent(FlexAlign.SpaceBetween)\\n      .padding({\\n        left: 60, right: 60\\n      })\\n\\n      //   4 底部白色大球\\n      Row() {\\n\\n      }\\n      .width(600)\\n      .height(600)\\n      .backgroundColor(\\"#fff\\")\\n      .position({\\n        bottom: 0,\\n        left: \\"50%\\"\\n      })\\n      .translate({\\n        x: \\"-50%\\",\\n        y: \\"70%\\"\\n      })\\n      .borderRadius(\\"50%\\")\\n\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .backgroundColor(\\"rgba(0,0,0,0.5)\\")\\n  }\\n\\n  /**\\n   * 录音中的 动态声纹波浪\\n   */\\n  @Builder\\n  vocalPrint() {\\n    Canvas(this.context)\\n      .onDisAppear(() => {\\n        clearInterval(this.voiceTimeId)\\n      })\\n      .width(\'80%\')\\n      .height(\'80%\')\\n      .onReady(() => {\\n        //可以在这里绘制内容。\\n        clearInterval(this.voiceTimeId)\\n        this.voiceTimeId = setInterval(() => {\\n          this.context.clearRect(0, 0, 1000, 1000)\\n          for (let index = 0; index < 35; index++) {\\n            const random = Math.floor(Math.random() * 10)\\n            let height = 20 + random\\n            this.context.fillRect(0 + index * 5, 32 - height / 2, 2, height);\\n          }\\n        }, 100)\\n      })\\n  }\\n}\\n```\\n\\n## 总结\\n\\n**一、清晰的枚举定义**\\n\\n代码中使用枚举类型`WXInputType`和`MessageType`分别明确了当前输入状态（语音或文本）以及消息类型，使得代码的可读性和可维护性大大增强。这种方式可以避免使用魔法数字，让开发者更容易理解代码的意图。\\n\\n**二、面向对象的消息类设计**\\n\\n定义了`ChatMessage`类来表示消息，清晰地封装了消息的各种属性，如消息类型、内容、时间、持续时间、录音转文字结果以及是否显示转好的文字等。这种面向对象的设计方式使得消息的处理更加模块化，方便在不同的地方进行复用和管理。\\n\\n**三、丰富的交互处理**\\n\\n1. 通过对触摸事件的处理，实现了按住说话的功能。在手指按下、移动和抬起时分别进行不同的状态判断和操作，包括判断是否碰到 “取消发送” 或 “转文字” 的区域，并根据不同状态进行相应的处理。\\n2. 底部聊天发送框根据输入状态动态切换显示内容，当输入类型为文本时显示文本输入相关的组件，当为语音时显示按住说话的按钮等，为用户提供了灵活的输入方式选择。\\n\\n**四、强大的页面构建和布局**\\n\\n1. 使用`build`方法构建页面结构，清晰地划分了顶部标题栏、聊天滚动容器和底部聊天发送框等部分，通过`Column`和`Row`的组合以及各种属性设置，实现了美观且合理的页面布局。\\n2. 在消息显示部分，通过`chatTextBuilder`方法构建文字消息的布局，包括时间显示、文本内容、背景颜色和图标等，使得消息展示更加清晰美观。\\n3. `talkContainerBuilder`方法构建了按住说话时的页面布局，包括声纹显示、取消和转文字按钮以及底部白色大球等元素，为用户提供了直观的交互界面。\\n\\n**五、动态声纹效果实现**\\n\\n通过`vocalPrint`方法利用`Canvas`绘制动态声纹波浪，在录音过程中通过定时器不断更新画布内容，实现了生动的声纹效果，增强了用户体验。\\n"}'),_={name:"鸿蒙开发技巧/HarmonyOS Next 微信聊天/带你实现HarmonyOS Next 微信聊天01/带你实现HarmonyOS Next 微信聊天01.md"};function R(I,s,M,H,N,X){return n(),a("div",null,[...s[0]||(s[0]=[l("",159)])])}const W=i(_,[["render",R]]);export{$ as __pageData,W as default};
